import chess, time, sys, multiprocessing as mp
import engine
from engine import Searcher, evaluate, MATE, PV

# --- improved evaluation with king safety ---
def eval2(board):
    score = evaluate(board)  # side-to-move perspective
    ws = 0
    nonpawn = 0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        nonpawn += PV[pt] * (len(board.pieces(pt, chess.WHITE)) + len(board.pieces(pt, chess.BLACK)))
    if nonpawn > 2600:
        for color, sign in ((chess.WHITE, 1), (chess.BLACK, -1)):
            k = board.king(color)
            kf = chess.square_file(k); kr = chess.square_rank(k)
            # pawn shield
            shield = 0
            pawns = board.pieces(chess.PAWN, color)
            for df in (-1, 0, 1):
                f = kf + df
                if 0 <= f < 8:
                    for dr in (1, 2):
                        r = kr + dr*sign if True else 0
                        r = kr + (dr if color == chess.WHITE else -dr)
                        if 0 <= r < 8 and chess.square(f, r) in pawns:
                            shield += 10 if dr == 1 else 5
                            break
            ws += sign * shield
            # enemy queen presence near king
            eq = board.pieces(chess.QUEEN, not color)
            for q in eq:
                d = chess.square_distance(q, k)
                ws -= sign * max(0, (4 - d)) * 8
            # open files near king
            for df in (-1, 0, 1):
                f = kf + df
                if 0 <= f < 8:
                    if not (board.pawns & chess.BB_FILES[f]):
                        ws -= sign * 15
            # castling rights bonus
            if board.has_castling_rights(color):
                ws += sign * 15
    return score + (ws if board.turn == chess.WHITE else -ws)

engine.evaluate = eval2

_searcher = None
def _init():
    global _searcher
    _searcher = Searcher()

def _work(args):
    fen, moves_uci, tlimit, maxdepth = args
    global _searcher
    s = _searcher
    board = chess.Board(fen)
    moves = [chess.Move.from_uci(u) for u in moves_uci]
    s.stop_time = time.time() + tlimit
    s.nodes = 0
    results = {}  # depth -> {uci: score}
    try:
        for depth in range(1, maxdepth+1):
            alpha = -MATE*2; beta = MATE*2
            res = {}
            # order: previous best first
            if depth > 1 and results.get(depth-1):
                prev = results[depth-1]
                moves.sort(key=lambda m: prev.get(m.uci(), -MATE*3), reverse=True)
            for m in moves:
                board.push(m)
                if board.is_repetition(3) or board.halfmove_clock >= 100:
                    score = 0
                else:
                    score = -s.search(board, depth-1, -beta, -alpha, 1)
                board.pop()
                res[m.uci()] = score
                if score > alpha: alpha = score
            results[depth] = res
            if len(s.tt) > 2_000_000: s.tt.clear()
    except TimeoutError:
        pass
    return results

class ParallelEngine:
    def __init__(self, nproc=30):
        self.pool = mp.Pool(nproc, initializer=_init)
        self.nproc = nproc
    def best_move(self, board, tlimit, maxdepth=40):
        moves = list(board.legal_moves)
        if len(moves) == 1: return moves[0], 0, 0
        # quick pre-order via shallow search for better distribution
        s = Searcher()
        s.stop_time = time.time() + 1.5
        pre = {}
        try:
            for m in moves:
                board.push(m); pre[m] = -s.search(board, 2, -MATE*2, MATE*2, 1); board.pop()
        except TimeoutError:
            pass
        moves.sort(key=lambda m: pre.get(m, -MATE*3), reverse=True)
        n = min(self.nproc, len(moves))
        buckets = [[] for _ in range(n)]
        for i, m in enumerate(moves):
            buckets[i % n].append(m.uci())
        fen = board.fen()
        tasks = [(fen, b, tlimit, maxdepth) for b in buckets]
        outs = self.pool.map(_work, tasks)
        # merge: for each depth, do all moves have scores?
        all_moves = [m.uci() for m in moves]
        merged = {}
        for out in outs:
            for d, res in out.items():
                merged.setdefault(d, {}).update(res)
        complete = [d for d in sorted(merged) if len(merged[d]) == len(all_moves)]
        if not complete:
            # fallback: pick from deepest available for each move at shared minimal depth
            d = min(max(out) for out in outs if out)
        else:
            d = complete[-1]
        scores = dict(merged[d])
        # also consider partial results at d+1: if a move has d+1 score, blend
        if d+1 in merged:
            for u, sc in merged[d+1].items():
                scores[u] = (scores.get(u, sc) + sc) / 2
        best_u = max(scores, key=scores.get)
        print(f"  depth {d} (partial d+1: {len(merged.get(d+1, {}))}/{len(all_moves)}) top: " +
              ", ".join(f"{u}:{scores[u]:.0f}" for u in sorted(scores, key=scores.get, reverse=True)[:5]), file=sys.stderr, flush=True)
        return chess.Move.from_uci(best_u), scores[best_u], d

if __name__ == "__main__":
    b = chess.Board(sys.argv[1])
    pe = ParallelEngine()
    t = time.time()
    print(pe.best_move(b, float(sys.argv[2])), time.time()-t)
