import chess, time, sys, multiprocessing as mp
import engine
from engine import Searcher, MATE
import pengine  # patches engine.evaluate with eval2

INF = MATE*2

def worker_main(inq, outq):
    s = Searcher()
    while True:
        job = inq.get()
        if job is None: return
        fen, uci, depth, lo, hi, deadline = job
        board = chess.Board(fen)
        m = chess.Move.from_uci(uci)
        board.push(m)
        s.stop_time = deadline
        s.nodes = 0
        try:
            if board.is_repetition(3) or board.halfmove_clock >= 100:
                score = 0
            else:
                score = -s.search(board, depth-1, -hi, -lo, 1)
            outq.put((uci, depth, lo, hi, score, s.nodes))
        except TimeoutError:
            outq.put((uci, depth, lo, hi, None, s.nodes))
        if len(s.tt) > 1_500_000: s.tt.clear()

class ParallelEngine:
    def __init__(self, nproc=31):
        self.nproc = nproc
        self.inqs = [mp.Queue() for _ in range(nproc)]
        self.outq = mp.Queue()
        self.procs = [mp.Process(target=worker_main, args=(self.inqs[i], self.outq), daemon=True) for i in range(nproc)]
        for p in self.procs: p.start()
        self.assign = {}  # uci -> worker index (persistent per game position family)

    def best_move(self, board, tlimit, maxdepth=40):
        moves = [m.uci() for m in board.legal_moves]
        if len(moves) == 1: return board.legal_moves.__iter__().__next__(), 0, 0
        fen = board.fen()
        deadline = time.time() + tlimit
        # assign moves to workers round-robin
        assign = {u: i % self.nproc for i, u in enumerate(moves)}
        scores = {u: 0 for u in moves}   # last exact/bound score
        exact = {u: False for u in moves}
        best_u = moves[0]; best_score = -INF; final_depth = 0
        total_nodes = 0
        for depth in range(1, maxdepth+1):
            if time.time() > deadline: break
            bestPrev = max(scores.values()) if depth > 1 else -INF
            pending = {}
            def send(u, lo, hi):
                pending[u] = (lo, hi)
                self.inqs[assign[u]].put((fen, u, depth, lo, hi, deadline))
            for u in moves:
                if depth <= 2:
                    send(u, -INF, INF)
                else:
                    lo = max(bestPrev - 60, -INF)
                    hi = max(scores[u], bestPrev) + 40
                    if lo >= hi: lo, hi = -INF, INF
                    send(u, lo, hi)
            new_scores = {}; new_exact = {}
            timed_out = False
            while pending:
                u, d, lo, hi, score, nodes = self.outq.get()
                total_nodes += nodes
                if d != depth: continue
                if score is None:
                    timed_out = True; del pending[u]; continue
                if score <= lo and lo > -INF:
                    new_scores[u] = lo; new_exact[u] = False; del pending[u]
                elif score >= hi and hi < INF:
                    # fail high: re-search with open window above
                    del pending[u]
                    send(u, score - 1, INF)
                else:
                    new_scores[u] = score; new_exact[u] = True; del pending[u]
            if timed_out or len(new_scores) < len(moves):
                # incomplete depth: if the best-so-far candidate got a higher exact score at this depth, adopt it
                if new_scores:
                    cand = max(new_scores, key=new_scores.get)
                    if new_exact.get(cand) and new_scores[cand] > best_score and cand != best_u:
                        print(f"  partial depth {depth}: switching to {cand} ({new_scores[cand]})", file=sys.stderr, flush=True)
                        best_u, best_score = cand, new_scores[cand]
                break
            scores = new_scores; exact = new_exact
            best_u = max(scores, key=scores.get); best_score = scores[best_u]; final_depth = depth
            top = sorted(scores, key=scores.get, reverse=True)[:4]
            print(f"  depth {depth} t={time.time()-(deadline-tlimit):.1f} nodes={total_nodes} best {best_u} {best_score} | " +
                  ", ".join(f"{u}:{scores[u]}" for u in top), file=sys.stderr, flush=True)
            if abs(best_score) > MATE - 1000: break
        # drain leftover messages
        while not self.outq.empty():
            try: self.outq.get_nowait()
            except Exception: break
        return chess.Move.from_uci(best_u), best_score, final_depth

if __name__ == "__main__":
    b = chess.Board(sys.argv[1])
    pe = ParallelEngine()
    t = time.time()
    print(pe.best_move(b, float(sys.argv[2])), time.time()-t)
